// @vitest-environment node
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { PIXEL_ICON_NAMES } from "./PixelIcon";

// Art is generated by scripts/pixel/generate-pixel-assets.py; this guards against a name without a PNG.
const ROOT = fileURLToPath(new URL("../../../", import.meta.url));
const EXTRA_ICON_NAMES: string[] = JSON.parse(
  readFileSync(path.join(ROOT, "scripts/pixel/extra-icon-names.json"), "utf8"),
);

const WARROOM_FILES = [
  "floor",
  "wall",
  "stripe",
  "table",
  "pin-working",
  "pin-blocked",
  "pin-waiting",
  "pin-watching",
  "pin-ready",
  "pin-error",
  "pin-merging",
  "station-argus",
  "station-patch",
  "station-medic",
  "station-weaver",
  "station-gate",
  "crate",
  "barrel",
  "sandbags",
  "lamp",
  "screen",
  "plate",
];

describe("pixel asset pack", () => {
  const iconNames = [...new Set<string>([...PIXEL_ICON_NAMES, ...EXTRA_ICON_NAMES])];

  it.each(iconNames)("has an icon for %s", (name) => {
    expect(existsSync(path.join(ROOT, "public/pixel/icons", `${name}.png`))).toBe(true);
  });

  it.each(WARROOM_FILES)("has the war-room file %s.png", (name) => {
    expect(existsSync(path.join(ROOT, "public/pixel/warroom", `${name}.png`))).toBe(true);
  });
});
